function normalizeClears(ranges){const sorted=ranges.map(r=>[...r]).sort((a,b)=>a[0]-b[0]),out=[];for(const r of sorted){const last=out[out.length-1];if(last&&r[0]<=last[1]+1)last[1]=Math.max(last[1],r[1]);else out.push(r)}return out}
