function villageCost(id){const d=villageFacilities.find(d=>d.id===id);if(!d)return null;const level=townLevel(id),step=id==='hall'?level-1:level;return {gold:Math.ceil(d.gold*Math.pow(1.55,step)),...Object.fromEntries(Object.keys(materialLabels).map(k=>[k,Math.ceil(d[k]*Math.pow(1.3,step))]))}}
function villageBuildReason(id){const d=villageFacilities.find(d=>d.id===id);if(!d)return '없는 시설입니다.';const level=townLevel(id);if(level>=d.max)return '최고 레벨입니다.';if(townLevel('hall')<d.unlock)return '마을회관 Lv.'+d.unlock+' 필요';if(id!=='hall'&&level>=townLevel('hall')*2)return '마을회관을 강화하면 시설 레벨 상한이 올라갑니다.';const c=villageCost(id),missing=[];if(s.gold<c.gold)missing.push('골드 '+Math.ceil(c.gold-s.gold).toLocaleString());for(const k of Object.keys(materialLabels))if(s.village.materials[k]<c[k])missing.push(materialLabels[k]+' '+(c[k]-s.village.materials[k]));return missing.length?'부족: '+missing.join(' · '):''}
function villageProduction(now=Date.now()){
 const v=s.village,level=townLevel('workshop'),elapsed=Math.max(0,Math.floor((now-v.productionAt)/60000)),minutes=Math.min(480,elapsed);
 return {minutes,elapsed,stock:Object.fromEntries(Object.keys(materialLabels).map(k=>[k,Math.min(workshopRate(level,k)*480,v.stock[k]+minutes*workshopRate(level,k))]))};
}
function settleVillageProduction(now=Date.now()){const v=s.village,p=villageProduction(now);if(!townLevel('workshop')){v.productionAt=now;return}if(p.elapsed>0){v.stock=p.stock;v.productionAt=p.elapsed>=480?now:v.productionAt+p.elapsed*60000}}
function buildVillage(id){const reason=villageBuildReason(id);if(reason){toast(reason);return false}const c=villageCost(id);settleVillageProduction();s.gold-=c.gold;for(const k of Object.keys(materialLabels))s.village.materials[k]-=c[k];s.village.buildings[id]++;if(id==='workshop')s.village.productionAt=Date.now();save();render();toast(villageFacilities.find(d=>d.id===id).name+' Lv.'+townLevel(id)+' · 시설 효과 적용');return true}
function collectVillageProduction(){settleVillageProduction();const v=s.village,keys=Object.keys(materialLabels);if(!keys.some(k=>v.stock[k]>0)){toast('아직 수령할 자재가 없습니다.');return false}const summary=keys.filter(k=>v.stock[k]>0).map(k=>materialLabels[k]+' +'+v.stock[k]).join(' · ');for(const k of keys){v.materials[k]+=v.stock[k];v.stock[k]=0}save();render();toast(summary);return true}
