function spawn(){bossTurn=0;bossShield=boss&&bossStyle()==='shield'?Math.round(enemyMax()*.2):0;poisonTurns=0;burnTurns=0;slowTurns=0;stunTurns=0;enemy=enemyMax();const monster=dungeon==='cave'&&boss?{name:'동굴 보스 · 심연의 망령',file:'assets/wraith.svg?v=e672e59ef103'}:boss?{name:s.floor%10===0?'챕터 보스 · 황금 파수왕':'스테이지 보스 · 철갑 수호자',file:'assets/guardian.svg?v=ffe96367f9d9'}:monsterRoster[(depth()-1+kills+(dungeon==='cave'?1:0))%monsterRoster.length];$('monsterLabel').textContent=monster.name;const img=document.querySelector('.enemy .sprite');img.src=monster.file;img.alt=monster.name+' 픽셀 몬스터';img.style.width=boss?'144px':'114px';img.style.height=boss?'144px':'114px';img.style.filter=boss&&s.floor%10===0?'hue-rotate(330deg) saturate(1.4)':'';if(window.TowerAction&&isActionTower())window.TowerAction.newWave();}

let motionTimers=[];
function clearMotions(){motionTimers.forEach(clearTimeout);motionTimers=[];const img=document.querySelector('.hero .sprite');if(img)img.src=heroIdle();for(const selector of ['.hero .sprite','.hero .equipmentOverlay','.enemy .sprite','#slashFx','#magicFx']){const el=document.querySelector(selector);if(el)el.style.animation='none'}}
function mirrorArmorMotion(){const img=document.querySelector('.hero .sprite'),overlay=document.querySelector('.hero .equipmentOverlay');if(overlay&&img){overlay.style.animation='none';void overlay.offsetWidth;overlay.style.animation=img.style.animation;}}
function attackMotion(retaliates){
if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
clearMotions();const heroImg=document.querySelector('.hero .sprite'),enemyImg=document.querySelector('.enemy .sprite'),fx=$('slashFx');
heroImg.src=heroIsMage()?'assets/mage.svg?v=fc6d1582a4a9':'assets/knight-attack.svg?v=d0aecd255cd2';void heroImg.offsetWidth;heroImg.style.animation=heroIsMage()?'magePulse .48s steps(5,end) both':'swordLunge .48s steps(5,end) both';enemyImg.style.animation='enemyHit .48s steps(5,end) both';fx.style.animation=heroIsMage()?'none':'slashPixel .48s steps(5,end) both';if(heroIsMage())magicMotion({names:['마법 평타'],type:'arcane'});mirrorArmorMotion();
motionTimers.push(setTimeout(()=>{heroImg.src=heroIdle();if(retaliates&&phase==='battle'&&!paused){enemyImg.style.animation='enemyStrike .3s steps(4,end) both';heroImg.style.animation='heroHit .3s steps(4,end) both';mirrorArmorMotion()}},500));
}
function magicMotion(spell){if(!spell.names.length)return;const fx=$('magicFx');fx.dataset.element=spell.type;fx.style.animation='none';void fx.offsetWidth;fx.style.animation='magicCast .65s steps(6,end) both';}
const todayUTC=()=>new Date().toISOString().slice(0,10);
function stopAuto(reason='자동 등반을 중단했습니다.'){autoRun=false;autoWait=0;autoReason=reason;if(autoSession){autoSession.note=reason;if(phase==='clear'||phase==='defeat')autoSession.ended=true;}}
function runBusy(){return autoRun||!!(autoSession&&!autoSession.ended)}
function focusExpedition(){if(!autoSession)return;view='tower';progressPinned=false;render()}
function endExpedition(){stopAuto(phase==='battle'?'자동 등반 OFF · 현재 전투는 끝까지 진행합니다.':'자동 등반을 중단했습니다.');render()}
function renderProgress(){
$('backgroundHome').hidden=!autoSession;$('showProgressCombat').hidden=!autoSession;
const session=autoSession,visible=!!session&&!progressHidden&&(view!=='tower'||progressPinned);
$('expeditionPopup').hidden=!visible;$('progressLauncher').hidden=!session||visible;$('progressBody').hidden=progressFolded;$('foldProgress').textContent=progressFolded?'+':'−';$('foldProgress').setAttribute('aria-expanded',String(!progressFolded));
if(!session){syncProgressWindow(null);return}
const status=session.ended?(session.note||'원정 종료'):phase==='clear'&&autoRun?autoWait+'초 뒤 다음 스테이지':paused?'전투 일시정지':autoRun?'자동 등반 진행 중':'현재 전투 후 종료';
$('progressTitle').textContent='스테이지 '+stageCode(s.floor)+' · '+status;$('progressState').textContent=phase==='battle'?(boss?'보스 전투':(isIdleExpedition()?'웨이브 ':'방 ')+(kills+1)+' / '+roomCount()):status;
$('progressHP').textContent=Math.max(0,hero)+' / '+maxHP();$('progressHPBar').style.width=Math.max(0,Math.min(100,hero/maxHP()*100))+'%';$('progressStageBar').style.width=Math.min(100,kills/roomCount()*100)+'%';
$('progressTickets').textContent=s.tickets+'장 보유 · '+session.spent+'장 사용';$('progressLoot').textContent='G '+session.gold+' · ◆ '+session.gems+' · 티켓 +'+session.tickets+'장';$('progressExtra').textContent='동굴식 자동 전투 · 골드/경험치 50% · 목표 '+(autoSession.target===null?'무제한':autoSession.target+'층')+' · 티켓 한도 '+autoSession.budget+'장 / 클리어 '+session.clears+'회 · 경험치 +'+session.xp+' · 무기 '+session.weapons+'개 · 방어구 '+(session.armors||0)+'개'+(session.materials?' · 건설 자재 +'+Object.values(session.materials).reduce((a,b)=>a+b,0):'');$('progressStop').disabled=!autoRun;$('progressBattle').textContent=session.ended?(phase==='map'?'탑 화면':'결과 보기'):'자동 원정 보기';$('progressLauncher').textContent='♜ '+stageCode(s.floor)+' · '+(session.ended?'원정 결과':'등반 진행');
syncProgressWindow({status,floor:stageCode(s.floor),hp:Math.max(0,hero)+' / '+maxHP(),ratio:Math.max(0,Math.min(100,hero/maxHP()*100)),wave:phase==='battle'?(boss?'보스':(isIdleExpedition()?'웨이브 ':'방 ')+(kills+1)+' / '+roomCount()):status,tickets:$('progressTickets').textContent,loot:$('progressLoot').textContent,extra:$('progressExtra').textContent,canStop:autoRun});
}
function syncProgressWindow(data){if(!progressWindow||progressWindow.closed){progressWindow=null;return}try{const d=progressWindow.document;if(!data){d.getElementById('pTitle').textContent='자동 등반이 없습니다.';d.getElementById('pStop').disabled=true;return}d.getElementById('pTitle').textContent='스테이지 '+data.floor;for(const key of ['status','hp','wave','tickets','loot','extra'])d.getElementById('p'+key).textContent=data[key];d.getElementById('pHPBar').style.width=data.ratio+'%';d.getElementById('pStop').disabled=!data.canStop;}catch{progressWindow=null}}
