function validateSave(raw){
if(!raw||raw.format!=='tower-rpg-save'||raw.version!==1||!raw.data||typeof raw.data!=='object')throw Error('지원하는 게임 저장 파일이 아닙니다.');const d=raw.data,out={saveSchemaVersion:1};if(d.saveSchemaVersion!==undefined&&d.saveSchemaVersion!==1)throw Error('더 최신 버전에서 만든 저장입니다. 게임을 업데이트한 뒤 불러오세요.');
const integer=(key,min,max,defaultValue)=>{const v=d[key]===undefined?defaultValue:d[key];if(!Number.isFinite(v)||!Number.isInteger(v)||v<min||v>max)throw Error(key+' 값이 올바르지 않습니다.');out[key]=v;};
for(const key of ['gold','gems','tickets'])integer(key,0,Number.MAX_VALUE,0);for(const key of ['atk','hp','crit','gear','skill','total','caveClears'])integer(key,0,key==='crit'?35:Number.MAX_SAFE_INTEGER,0);integer('level',1,Math.floor(Number.MAX_SAFE_INTEGER/100),1);integer('xp',0,out.level*100-1,0);integer('skillPoints',0,Number.MAX_SAFE_INTEGER,0);integer('best',1,Number.MAX_SAFE_INTEGER,1);integer('floor',1,out.best,1);integer('caveBest',1,Number.MAX_SAFE_INTEGER,1);
out.skillLevels={};for(const n of skillNodes){const lv=d.skillLevels?.[n.id];if(lv!==undefined){if(!Number.isInteger(lv)||lv<1||lv>10)throw Error('스킬 강화 레벨이 올바르지 않습니다.');out.skillLevels[n.id]=lv}}
out.tree={};for(const n of skillNodes){const r=d.tree?.[n.id]||0;if(!Number.isInteger(r)||r<0||r>n.max)throw Error('스킬 랭크가 올바르지 않습니다.');if(r)out.tree[n.id]=r}for(const n of skillNodes)if(out.tree[n.id]&&n.requires&&(out.tree[n.requires[0]]||0)<n.requires[1])throw Error('스킬 선행 조건이 맞지 않습니다.');for(const n of skillNodes)if(out.tree[n.id]&&pathConflict(n,out.tree))throw Error('서로 배타적인 전문화 경로가 함께 선택되어 있습니다.');if(Object.values(out.tree).reduce((a,b)=>a+b,0)+out.skillPoints>out.level-1)throw Error('레벨과 스킬 포인트가 맞지 않습니다.');
if(!Array.isArray(d.cleared)||d.cleared.some(v=>!isStage(v)))throw Error('클리어 기록이 올바르지 않습니다.');
if(d.clearedRanges!==undefined&&(!Array.isArray(d.clearedRanges)||d.clearedRanges.some(r=>!Array.isArray(r)||r.length!==2||!isStage(r[0])||!isStage(r[1])||r[0]>r[1])))throw Error('클리어 구간 기록이 올바르지 않습니다.');
out.clearedRanges=normalizeClears([...(d.clearedRanges||[]),...d.cleared.map(n=>[n,n])]);out.cleared=[...new Set(d.cleared.filter(n=>n<=100))];out.best=out.clearedRanges.reduce((best,r)=>Math.max(best,r[1]+1),out.best);out.endlessStages=true;out.claimed=d.claimed===true;out.ticketClaimDate=typeof d.ticketClaimDate==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d.ticketClaimDate)?d.ticketClaimDate:'';
if(!Array.isArray(d.inventory)||d.inventory.length>10000)throw Error('무기 목록이 올바르지 않습니다.');const ids=new Set();out.inventory=d.inventory.map(w=>{const def=weaponCatalog.find(v=>v.source===w.source&&v.name===w.name);if(!def||!Object.keys(rarityLabel).includes(w.rarity)||!isStage(w.tier)||!Number.isFinite(w.attack)||!Number.isInteger(w.attack)||w.attack<0||!Number.isSafeInteger(w.count)||w.count<1||w.count>1e9)throw Error('무기 데이터가 올바르지 않습니다.');const id=[w.source,w.rarity,def.type,w.tier].join('-');if(w.id!==id||ids.has(id))throw Error('중복되거나 잘못된 무기 ID입니다.');ids.add(id);const magic=w.magic||0;if(!Number.isFinite(magic)||!Number.isInteger(magic)||magic<0)throw Error('마법력이 올바르지 않습니다.');return{id,name:def.name,rarity:w.rarity,tier:w.tier,attack:w.attack,magic,count:w.count,source:def.source,kind:def.kind,catalogId:def.id}});out.equipped=ids.has(d.equipped)?d.equipped:null;
if(d.armorInventory!==undefined&&!Array.isArray(d.armorInventory))throw Error('방어구 목록이 올바르지 않습니다.');if((d.armorInventory||[]).length>3000)throw Error('방어구 목록이 너무 큽니다.');const armorIds=new Set();out.armorInventory=(d.armorInventory||[]).map(w=>{const def=armorDefs.find(v=>v.id===w.defId);if(!def||!gradeMult[w.rarity]||!isStage(w.tier)||!Number.isSafeInteger(w.count)||w.count<1||w.count>1e9)throw Error('방어구 데이터가 올바르지 않습니다.');const item=createArmor(def,w.rarity,w.tier);if(w.id!==item.id||armorIds.has(item.id))throw Error('방어구 ID가 올바르지 않습니다.');armorIds.add(item.id);item.count=w.count;return item});out.equippedArmor={};for(const slot of ['armor','helmet','boots']){const id=d.equippedArmor?.[slot];out.equippedArmor[slot]=out.armorInventory.some(w=>w.id===id&&w.slot===slot)?id:null;}out.armorStarterClaimed=d.armorStarterClaimed===true;
const validDiscoveries=new Set(weaponCatalog.flatMap(def=>Object.keys(rarityLabel).map(r=>def.id+':'+r)));if(d.weaponDiscoveries!==undefined&&(!Array.isArray(d.weaponDiscoveries)||d.weaponDiscoveries.length>48||d.weaponDiscoveries.some(k=>!validDiscoveries.has(k))))throw Error('무기 도감 기록이 올바르지 않습니다.');out.weaponDiscoveries=[...new Set([...(d.weaponDiscoveries||[]),...out.inventory.map(w=>weaponCatalog.find(v=>v.source===w.source&&v.name===w.name).id+':'+w.rarity)])];
out.village=readVillage(d.village,true);const a=d.autoConfig||{};out.autoConfig={target:isStage(a.target)&&(d.endlessStages||a.target!==100)?a.target:null,budget:Number.isInteger(a.budget)&&a.budget>=1&&a.budget<=1000?a.budget:10};out.last=Date.now();return out;}
function stageImport(raw){pendingSave=validateSave(raw);$('savePreview').textContent='Lv. '+pendingSave.level+' · 최고 '+pendingSave.best+'층 · 골드 '+pendingSave.gold.toLocaleString()+' · 무기 '+pendingSave.inventory.length+'종 / 적용하면 현재 저장을 대체합니다. 자동 백업은 남습니다.';render()}
$('exportSave').onclick=()=>{const blob=new Blob([JSON.stringify({format:'tower-rpg-save',version:1,exportedAt:new Date().toISOString(),data:s},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tower-save-'+todayUTC()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('현재 진행을 저장 파일로 내보냈습니다.')};
$('loadSave').onclick=()=>$('saveFile').click();$('saveFile').onchange=async e=>{pendingSave=null;try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('2MB 이하의 저장 파일을 선택하세요.');stageImport(JSON.parse(await file.text()))}catch(err){$('savePreview').textContent='불러오기 실패: '+err.message;render()}finally{e.target.value=''}};
$('applySave').onclick=()=>{if(!pendingSave||runBusy())return;try{localStorage.setItem('eternity-before-import',JSON.stringify({format:'tower-rpg-save',version:1,data:s}));localStorage.setItem('eternity-stages-v2',JSON.stringify(pendingSave));s=pendingSave;window.GameStorage?.resumeAfterImport();pendingSave=null;autoSession=null;stopAuto('');clearMotions();phase='map';view='home';selected=s.best;offline=0;collectionCache.inventory='';collectionCache.skills='';collectionCache.codex='';$('autoTarget').value=s.autoConfig.target??'';$('autoBudget').value=s.autoConfig.budget;save();$('savePreview').textContent='저장을 적용했습니다. 이전 진행은 자동 백업에서 복구할 수 있습니다.';render();toast('저장 불러오기 완료')}catch{toast('백업 또는 저장 기록에 실패해 불러오기를 중단했습니다.')}};
