for(const id of ['autoTarget','autoBudget'])$(id).onchange=()=>{if(runBusy())return;const target=readAutoTarget(),budget=Number($('autoBudget').value);if((target===null||isStage(target))&&Number.isInteger(budget)&&budget>=1&&budget<=1000){s.autoConfig={target,budget};save()}};
