$('armorList').onclick=e=>{const id=e.target.dataset.wear,item=s.armorInventory.find(w=>w.id===id);if(!item)return;s.equippedArmor[item.slot]=id;save();render();toast(item.name+' 장착 · 전투 외형에 반영됩니다.')};
$('armorSlots').onclick=e=>{const slot=e.target.dataset.unwear;if(!['armor','helmet','boots'].includes(slot))return;s.equippedArmor[slot]=null;save();render()};
$('armorGift').onclick=()=>{if(s.armorStarterClaimed)return;for(const def of armorDefs.filter(d=>d.source==='tower')){const item=createArmor(def,'common',1),old=s.armorInventory.find(w=>w.id===item.id);if(old)old.count++;else s.armorInventory.push(item)}s.armorStarterClaimed=true;save();render();toast('시작 갑옷·투구·신발을 받았습니다. 직접 장착해보세요.')};
$('forgeWeapon').onchange=e=>{forgeKey=e.target.value;forgeMessage='';render()};$('forgeGrade').onchange=e=>{forgeRarity=e.target.value;forgeMessage='';render()};$('forgeCombine').onclick=()=>combineWeapons(forgePreview);
