for(const w of s.inventory){const def=weaponDef(w);if(def){w.catalogId=def.id;w.kind=def.kind;}if(!w.magic)w.magic=0;trackWeaponDiscovery(w);}
s.tickets=Number.isFinite(s.tickets)?Math.max(0,Math.floor(s.tickets)):5;save();
resetCombatStats();spawn();log('스테이지를 선택하고 모험을 시작하세요.');render();
setInterval(()=>{if(phase==='clear'&&autoRun){if(autoWait>0)autoWait--;if(autoWait===0)start(s.floor+1,true);else render();return}if(phase!=='battle'||paused)return;if(isActionTower()&&window.TowerAction)return;tick++;let critical=Math.random()<critChance(),dmg=Math.round(attack()*(critical?(critMultiplier()):1))+(tick%5===0?legacySkillDamage()+Math.round(attack()*1.2*activeRank('storm')*(1+treeBonus('skillDamage'))):0);const spell=spellHit();dmg+=spell.damage;dmg=resolvePlayerHit(dmg,spell);if(hasPerk('leech')&&tick%6===0)hero=Math.min(maxHP(),hero+Math.round(maxHP()*.05*healMultiplier()));lastSpell=spell.names.length?spell.names.join(' · ')+(spell.crit?' (마법 치명타)':''):'';attackMotion(enemy>dmg);magicMotion(spell);showIdleSkills(spell,critical);enemy-=dmg;if((critical||spell.crit)&&activeRank('drain')){const before=hero;hero=Math.min(maxHP(),hero+Math.round(maxHP()*.05*activeRank('drain')*healMultiplier()));if(hero>before)window.SkillFX?.emit(['생명 흡수'],{channel:'idle'});}$('damage').textContent=(critical?'✧ ':'')+dmg;$('damage').style.animation='none';void $('damage').offsetWidth;$('damage').style.animation='float 1s forwards';
if(enemy<=0){const isBoss=boss;giveLoot({gold:Math.round((dungeon==='cave'?60:20)*depth()*(isBoss?4:isIdleExpedition()?6:1))});if(dungeon==='tower')gainXP(isBoss?40:30);else{if(Math.random()<.3)giveLoot({gems:1});if(Math.random()<.15)giveLoot({tickets:1});}dropWeapon(isBoss);dropArmor(isBoss);s.total++;kills++;if(isBoss)complete();else{boss=kills===roomCount()-1;spawn();log(boss?'마지막 웨이브 — 수호자가 나타났습니다!':'웨이브 '+kills+' 클리어! 다음 구역으로 전진합니다.')}}else{takeHit();if(hero<=0){hero=0;phase='defeat';if(autoSession){stopAuto('패배로 자동 등반이 종료되었습니다.');autoSession.ended=true;}log('도전 종료. 강화 후 다시 입장하세요.')}}render();save()},1000);window.addEventListener('pagehide',()=>{save();if(progressWindow&&!progressWindow.closed){try{const d=progressWindow.document;d.getElementById('pstatus').textContent='게임이 닫혀 원정이 중단되었습니다.';d.getElementById('pStop').disabled=true;}catch{}}});

